import re
import string


class LongestWord:

    def __init__(self):
        self._word_list = []

    def add_word(self, word):
        self._word_list.append(word)

    @property
    def word_list(self):
        return list(self._word_list)

    @word_list.setter
    def word_list(self, value):
        if isinstance(value, (list, tuple)):
            self._word_list = list(value)
        else:
            raise TypeError("word_list must be a list or tuple")

    def find_longest_word(self, sentence):
        cleaned_words = self._extract_clean_words(sentence)
        longest_word = ""
        for word in cleaned_words:
            if self._is_in_word_list(word) and self._is_longer(word, longest_word):
                longest_word = word
        return longest_word

    def _extract_clean_words(self, sentence):
        sentence = sentence.lower()
        sentence = re.sub('[%s]' % re.escape(string.punctuation), '', sentence)
        return re.split(' ', sentence)

    def _is_in_word_list(self, word):
        return word in self._word_list

    def _is_longer(self, word, other_word):
        return len(word) > len(other_word)
